INSERT INTO information_objects(object_id,object_type,object_name,status,requires_producer,requires_consumer,description,created_at) SELECT CONCAT('table:',table_name),'table',table_name,'active',0,0,'MariaDB basetabell',UTC_TIMESTAMP(3) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_type='BASE TABLE';
INSERT INTO information_objects(object_id,object_type,object_name,status,requires_producer,requires_consumer,description,created_at) SELECT CONCAT('view:',table_name),'view',table_name,'active',0,0,'MariaDB read-model view',UTC_TIMESTAMP(3) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_type='VIEW';
