INSERT INTO information_objects(object_id,object_type,object_name,status,requires_producer,requires_consumer,description,created_at) SELECT CONCAT('event:',event_type),'event',event_type,status,IF(direction IN ('nodered_to_home_assistant','bidirectional'),1,0),IF(direction IN ('home_assistant_to_nodered','bidirectional'),1,0),description,UTC_TIMESTAMP(3) FROM ha_event_registry WHERE status<>'deprecated';
